// Some portions generated by Claude
/** Timings, limits and storage keys of the graph explorer. */

// Leave enough room for the edge anchors and the selection halo, while
// keeping ordinary connected components dense enough to inspect at once.
export const INCREMENTAL_LAYOUT_DURATION = 720;

export const PROGRAMMATIC_NODE_MOTION_DURATION = 560;

export const DOUBLE_TAP_DELAY = 360;

export const DOUBLE_TAP_DISTANCE = 38;

export const TAP_MOVE_TOLERANCE = 9;

export const DOUBLE_TAP_ZOOM_SENSITIVITY = 0.012;

export const HISTORY_LIMIT = 32;

export const INTERACTIVE_TRANSFORM_COMMIT_DELAY = 96;

export const DEFAULT_QUERY = "SELECT ?source ?predicate ?target WHERE { ?source ?predicate ?target } LIMIT 100";

export const SHOW_VALUES_STORAGE_KEY = "graph-field-show-values-v1";

export const SHOW_LABELS_STORAGE_KEY = "graph-field-show-labels-v1";

export const DETAILS_ITEM_LIMIT = 12;

export const LEGEND_TYPE_LIMIT = 6;

export const LABEL_WAIT_MS = 1500;

// Filters shown before "N more filters"; searching shows every match.
export const FACET_LIST_LIMIT = 7;

/** Up to this many drawn nodes every node shows its "+N" badge; above it only the active and selected ones do. */
export const MORE_BADGE_NODE_LIMIT = 150;

/** How close (CSS pixels) a click or the mouse has to come to an edge to pick it. */
export const EDGE_HIT_PIXELS = 7;

/** At most this many rows of a query another Workbench page handed over with "Add to graph" (it has no LIMIT). */
export const QUEUED_QUERY_ROW_LIMIT = 5000;

/**
 * Expand pages past loaded statements that did not fit into its query for at most this many pages before it says so
 * (and points at Expand by relation) instead of looking further.
 */
export const EXPAND_PAGE_LIMIT = 25;

/** Above this many drawn nodes, nodes have no drop shadow: repainting hundreds of shadows makes the canvas lag. */
export const SHADOW_NODE_LIMIT = 150;

/** From this many drawn nodes the canvas renderer (dots, straight edges, labels on zoom) replaces the SVG one. */
export const LARGE_GRAPH_NODES = 500;
